import { browser } from "$app/environment";
import { authState } from "$lib/stores/auth.store";
import authService from "$lib/api/services/auth.service";

async function handleLogin(_, isInitialized, error, isLoading) {
	if (!$.get(isInitialized)) {
		$.set(error, "Nostr extension not detected. Please install Alby extension.");
		return;
	}

	$.set(isLoading, true);
	$.set(error, null);

	try {
		if (!window.nostr) {
			throw new Error("Nostr extension not available");
		}

		const pubkey = await window.nostr.getPublicKey();

		if (!pubkey) {
			throw new Error("No public key returned from Nostr extension");
		}

		const { challenge } = await authService.getLoginChallenge();

		const event = {
			kind: 22242,
			created_at: Math.floor(Date.now() / 1000),
			content: challenge,
			tags: [
				["relay", window.location.origin],
				["challenge", challenge]
			],
			pubkey
		};

		if (!window.nostr) {
			throw new Error("Nostr extension not available");
		}

		const rawSignedEvent = await window.nostr.signEvent(event);

		const res = await authService.loginWithNostr({
			event: rawSignedEvent,
			challenge,
			authMethod: "alby"
		});

		if (res.access_token) {
			authState.setupAuthData(res.access_token, "alby", pubkey, res.user);
		}
	} catch(err) {
		console.error("Nostr login error:", err);
		$.set(error, err?.message || "Failed to sign in with Nostr", true);
	} finally {
		$.set(isLoading, false);
	}
}

